import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_KEY', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_request_signature(req):
    """Verify HMAC signature for write operations"""
    sig = req.headers.get('X-Request-Signature', '')
    timestamp = req.headers.get('X-Request-Timestamp', '')
    if not sig or not timestamp:
        return False
    if abs(time.time() - float(timestamp)) > 300:
        return False
    payload = f"{req.method}:{req.path}:{timestamp}:{req.get_data(as_text=True)}"
    expected = hmac.new(SECRET_HMAC_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible querying."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build dynamic query based on provided parameters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT id, username, email, department, role FROM users WHERE {where_clause}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID"""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, department, role FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user - requires signed request"""
    if not verify_request_signature(request):
        return jsonify({'error': 'Invalid signature'}), 403
    data = request.get_json()
    db = get_db()
    db.execute(
        "INSERT INTO users (username, email, department, role) VALUES (?, ?, ?, ?)",
        (data['username'], data['email'], data['department'], data['role'])
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.3.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
